// Crisis and support resources. Shown from config only, never generated by a model
// (docs/guardrails/ai-safety.md). Verify every number before each release.

export interface CrisisResource {
  id: string;
  country: "IN" | "US" | "GB" | "GLOBAL";
  name: string;
  detail: string;
  /** tel:, sms: or https: link */
  href: string;
  linkLabel: string;
}

export const CRISIS_RESOURCES: CrisisResource[] = [
  {
    id: "tele-manas",
    country: "IN",
    name: "Tele-MANAS (India)",
    detail: "Free, 24/7: 14416 or 1-800-891-4416",
    href: "tel:14416",
    linkLabel: "Call 14416",
  },
  {
    id: "988",
    country: "US",
    name: "988 Suicide & Crisis Lifeline (US)",
    detail: "Call or text 988",
    href: "tel:988",
    linkLabel: "Call 988",
  },
  {
    id: "samaritans",
    country: "GB",
    name: "Samaritans (UK)",
    detail: "116 123",
    href: "tel:116123",
    linkLabel: "Call 116 123",
  },
  {
    id: "findahelpline",
    country: "GLOBAL",
    name: "Elsewhere",
    detail: "findahelpline.com lists free services by country",
    href: "https://findahelpline.com",
    linkLabel: "Open findahelpline.com",
  },
];

/** Resources for a country first, then the global fallback. */
export function crisisResourcesFor(country: string | null | undefined): CrisisResource[] {
  const local = CRISIS_RESOURCES.filter((r) => r.country === country);
  const rest = CRISIS_RESOURCES.filter((r) => r.country !== country);
  return [...local, ...rest];
}

/** Best-effort country from the IANA timezone (no location data is used). */
export function countryFromTimezone(tz: string): "IN" | "US" | "GB" | null {
  if (tz === "Asia/Kolkata" || tz === "Asia/Calcutta") return "IN";
  if (tz === "Europe/London") return "GB";
  if (tz.startsWith("America/") || tz.startsWith("US/") || tz === "Pacific/Honolulu") return "US";
  return null;
}
